// src/main.js
import { createApp } from 'vue'
import App from './App.vue'
import router from './router'
import store from './store'

import { loadFonts } from './plugins/webfontloader'

// Vuetify 3
import 'vuetify/styles'
import { createVuetify } from 'vuetify'
import { VApp, VMain, VBtn, VCard, VTextField, VContainer } from 'vuetify/components'
const vuetify = createVuetify({
  components: {
    VApp, VMain, VBtn, VCard, VTextField, VContainer
  }
})

// Font yuklash
loadFonts()

// App yaratish
const app = createApp(App)

// Telegram WebApp
if (window.Telegram?.WebApp) {
  app.config.globalProperties.$tg = window.Telegram.WebApp
  app.config.globalProperties.$user = window.Telegram.WebApp.initDataUnsafe.user
}

// Pluginlar
app.use(router).use(store).use(vuetify).mount('#app')